function tokenizeExpression(source) {
  const tokens=[];let index=0;
  while(index<source.length){
    const char=source[index];
    if(/\s/.test(char)){index++;continue;}
    const match=source.slice(index).match(/^[0-9]+(?:\.[0-9]+)?/);
    if(match){tokens.push({type:"number",value:Number(match[0]),start:index});index+=match[0].length;continue;}
    if("+-*/".includes(char)){tokens.push({type:"operator",value:char,start:index});index++;continue;}
    if("()".includes(char)){tokens.push({type:"paren",value:char,start:index});index++;continue;}
    throw new SyntaxError("Unexpected character at "+index);
  }
  return tokens;
}

