function orderTasks(graph) {
  const visiting=new Set(),done=new Set(),result=[];
  function visit(task){
    if(!Object.hasOwn(graph,task))throw new Error("Missing dependency: "+task);
    if(visiting.has(task))throw new Error("Dependency cycle: "+task);
    if(done.has(task))return;
    visiting.add(task);for(const dependency of graph[task])visit(dependency);
    visiting.delete(task);done.add(task);result.push(task);
  }
  for(const task of Object.keys(graph))visit(task);
  return result;
}

