function diffJSON(before,after) {
  const plain=v=>v!==null&&typeof v==="object"&&!Array.isArray(v);
  function equal(a,b){
    if(a===b)return true;
    if(Array.isArray(a)&&Array.isArray(b))return a.length===b.length&&a.every((v,i)=>equal(v,b[i]));
    if(plain(a)&&plain(b)){const keys=Object.keys(a);return keys.length===Object.keys(b).length&&keys.every(k=>Object.hasOwn(b,k)&&equal(a[k],b[k]));}
    return false;
  }
  const result=[],escape=key=>key.replace(/~/g,"~0").replace(/\//g,"~1");
  function visit(a,b,path){
    if(equal(a,b))return;
    if(plain(a)&&plain(b)){
      for(const key of [...new Set([...Object.keys(a),...Object.keys(b)])].sort()){
        const next=path+"/"+escape(key);
        if(!Object.hasOwn(b,key))result.push({op:"remove",path:next});
        else if(!Object.hasOwn(a,key))result.push({op:"add",path:next,value:structuredClone(b[key])});
        else visit(a[key],b[key],next);
      }
    }else result.push({op:"replace",path,value:structuredClone(b)});
  }
  visit(before,after,"");return result;
}

