function parseEnvironment(env,schema) {
  const values={},errors=[];
  const put=(key,value)=>Object.defineProperty(values,key,{value,enumerable:true,writable:true,configurable:true});
  for(const [key,rule] of Object.entries(schema)){
    const present=Object.hasOwn(env,key),raw=present?env[key]:undefined;
    if(!present||raw===""){if(Object.hasOwn(rule,"default"))put(key,rule.default);else if(rule.required)errors.push(key+": required");continue;}
    let value,valid=typeof raw==="string";
    if(rule.type==="string")value=raw;
    else if(rule.type==="number"){value=valid?Number(raw):NaN;valid=valid&&raw.trim()!==""&&Number.isFinite(value);}
    else if(rule.type==="boolean"){valid=valid&&(raw==="true"||raw==="false");value=raw==="true";}
    else valid=false;
    if(valid)put(key,value);else errors.push(key+": invalid "+rule.type);
  }
  return {values,errors};
}

